/// Every client to server message of this schema.
#[derive(Clone, Copy, PartialEq, Debug)]
#[allow(clippy::large_enum_variant)] // inline, allocation-free values; transient on network threads
#[non_exhaustive]
pub enum Inbound {
    /// See [`Hello`].
    Hello(Hello),
    /// See [`Move`].
    Move(Move),
    /// See [`MoveClaim`].
    MoveClaim(MoveClaim),
    /// See [`Cast`].
    Cast(Cast),
    /// See [`Interact`].
    Interact(Interact),
    /// See [`Choose`].
    Choose(Choose),
    /// See [`Extension`].
    Extension(Extension),
    /// See [`SnapshotAck`].
    SnapshotAck(SnapshotAck),
    /// See [`Goodbye`].
    Goodbye(Goodbye),
    /// See [`Linked`].
    Linked(Linked),
}

impl Inbound {
    /// The registered id of the message.
    #[must_use]
    pub const fn id(&self) -> ::mantis_core::wire::MessageId {
        match self {
            Self::Hello(_) => <Hello as ::mantis_core::wire::Message>::ID,
            Self::Move(_) => <Move as ::mantis_core::wire::Message>::ID,
            Self::MoveClaim(_) => <MoveClaim as ::mantis_core::wire::Message>::ID,
            Self::Cast(_) => <Cast as ::mantis_core::wire::Message>::ID,
            Self::Interact(_) => <Interact as ::mantis_core::wire::Message>::ID,
            Self::Choose(_) => <Choose as ::mantis_core::wire::Message>::ID,
            Self::Extension(_) => <Extension as ::mantis_core::wire::Message>::ID,
            Self::SnapshotAck(_) => <SnapshotAck as ::mantis_core::wire::Message>::ID,
            Self::Goodbye(_) => <Goodbye as ::mantis_core::wire::Message>::ID,
            Self::Linked(_) => <Linked as ::mantis_core::wire::Message>::ID,
        }
    }

    /// Appends the payload encoding (without the id).
    pub fn encode(&self, out: &mut Vec<u8>) {
        match self {
            Self::Hello(m) => ::mantis_core::wire::encode_into(m, out),
            Self::Move(m) => ::mantis_core::wire::encode_into(m, out),
            Self::MoveClaim(m) => ::mantis_core::wire::encode_into(m, out),
            Self::Cast(m) => ::mantis_core::wire::encode_into(m, out),
            Self::Interact(m) => ::mantis_core::wire::encode_into(m, out),
            Self::Choose(m) => ::mantis_core::wire::encode_into(m, out),
            Self::Extension(m) => ::mantis_core::wire::encode_into(m, out),
            Self::SnapshotAck(m) => ::mantis_core::wire::encode_into(m, out),
            Self::Goodbye(m) => ::mantis_core::wire::encode_into(m, out),
            Self::Linked(m) => ::mantis_core::wire::encode_into(m, out),
        }
    }
}

/// Hand-written validators: one required method per inbound message, so a
/// new message without a validator does not compile (plan 6.7, decision 0017).
pub trait Validators {
    /// Validates a decoded [`Hello`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_hello(&self, msg: &Hello) -> Result<(), ::mantis_core::wire::ValidationError>;
    /// Validates a decoded [`Move`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_move(&self, msg: &Move) -> Result<(), ::mantis_core::wire::ValidationError>;
    /// Validates a decoded [`MoveClaim`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_move_claim(&self, msg: &MoveClaim) -> Result<(), ::mantis_core::wire::ValidationError>;
    /// Validates a decoded [`Cast`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_cast(&self, msg: &Cast) -> Result<(), ::mantis_core::wire::ValidationError>;
    /// Validates a decoded [`Interact`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_interact(&self, msg: &Interact) -> Result<(), ::mantis_core::wire::ValidationError>;
    /// Validates a decoded [`Choose`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_choose(&self, msg: &Choose) -> Result<(), ::mantis_core::wire::ValidationError>;
    /// Validates a decoded [`Extension`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_extension(&self, msg: &Extension) -> Result<(), ::mantis_core::wire::ValidationError>;
    /// Validates a decoded [`SnapshotAck`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_snapshot_ack(&self, msg: &SnapshotAck) -> Result<(), ::mantis_core::wire::ValidationError>;
    /// Validates a decoded [`Goodbye`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_goodbye(&self, msg: &Goodbye) -> Result<(), ::mantis_core::wire::ValidationError>;
    /// Validates a decoded [`Linked`].
    ///
    /// # Errors
    /// The reason the message is refused.
    fn validate_linked(&self, msg: &Linked) -> Result<(), ::mantis_core::wire::ValidationError>;
}

impl Inbound {
    /// Runs this message's hand-written validator. Adapters that build `Inbound`
    /// values from their own byte formats go through the same validators.
    ///
    /// # Errors
    /// [`::mantis_core::wire::WireError::Rejected`] with the validator's reason.
    pub fn validate(&self, validators: &impl Validators) -> Result<(), ::mantis_core::wire::WireError> {
        let (message, result) = match self {
            Self::Hello(m) => ("Hello", validators.validate_hello(m)),
            Self::Move(m) => ("Move", validators.validate_move(m)),
            Self::MoveClaim(m) => ("MoveClaim", validators.validate_move_claim(m)),
            Self::Cast(m) => ("Cast", validators.validate_cast(m)),
            Self::Interact(m) => ("Interact", validators.validate_interact(m)),
            Self::Choose(m) => ("Choose", validators.validate_choose(m)),
            Self::Extension(m) => ("Extension", validators.validate_extension(m)),
            Self::SnapshotAck(m) => ("SnapshotAck", validators.validate_snapshot_ack(m)),
            Self::Goodbye(m) => ("Goodbye", validators.validate_goodbye(m)),
            Self::Linked(m) => ("Linked", validators.validate_linked(m)),
        };
        result.map_err(|reason| ::mantis_core::wire::WireError::Rejected { message, reason })
    }
}

/// Decodes one inbound message without validating it. Unknown ids fail closed.
/// Adapters use this; the server validates with [`Inbound::validate`].
///
/// # Errors
/// [`::mantis_core::wire::WireError`] for an unknown id or a payload that does
/// not decode exactly.
pub fn parse_inbound(
    id: ::mantis_core::wire::MessageId,
    bytes: &[u8],
) -> Result<Inbound, ::mantis_core::wire::WireError> {
    Ok(match id.0 {
        1 => Inbound::Hello(::mantis_core::wire::decode_message(bytes)?),
        2 => Inbound::Move(::mantis_core::wire::decode_message(bytes)?),
        3 => Inbound::MoveClaim(::mantis_core::wire::decode_message(bytes)?),
        4 => Inbound::Cast(::mantis_core::wire::decode_message(bytes)?),
        5 => Inbound::Interact(::mantis_core::wire::decode_message(bytes)?),
        6 => Inbound::Choose(::mantis_core::wire::decode_message(bytes)?),
        7 => Inbound::Extension(::mantis_core::wire::decode_message(bytes)?),
        8 => Inbound::SnapshotAck(::mantis_core::wire::decode_message(bytes)?),
        9 => Inbound::Goodbye(::mantis_core::wire::decode_message(bytes)?),
        17 => Inbound::Linked(::mantis_core::wire::decode_message(bytes)?),
        _ => return Err(::mantis_core::wire::WireError::UnknownMessage(id)),
    })
}

/// Decodes and validates one inbound message. Unknown ids fail closed.
///
/// # Errors
/// [`::mantis_core::wire::WireError`] for an unknown id, a payload that does not
/// decode exactly, or a validator refusal.
pub fn decode_inbound(
    id: ::mantis_core::wire::MessageId,
    bytes: &[u8],
    validators: &impl Validators,
) -> Result<Inbound, ::mantis_core::wire::WireError> {
    let msg = parse_inbound(id, bytes)?;
    msg.validate(validators)?;
    Ok(msg)
}

/// Every server to client message of this schema.
#[derive(Clone, Copy, PartialEq, Debug)]
#[allow(clippy::large_enum_variant)] // inline, allocation-free values; transient on network threads
#[non_exhaustive]
pub enum Outbound {
    /// See [`Welcome`].
    Welcome(Welcome),
    /// See [`Refuse`].
    Refuse(Refuse),
    /// See [`SetPosition`].
    SetPosition(SetPosition),
    /// See [`ExtensionRefused`].
    ExtensionRefused(ExtensionRefused),
    /// See [`ExtensionMessage`].
    ExtensionMessage(ExtensionMessage),
    /// See [`FeatureState`].
    FeatureState(FeatureState),
    /// See [`PermittedModules`].
    PermittedModules(PermittedModules),
    /// See [`Transferred`].
    Transferred(Transferred),
    /// See [`ResumeTicket`].
    ResumeTicket(ResumeTicket),
    /// See [`HandOff`].
    HandOff(HandOff),
}

impl Outbound {
    /// The registered id of the message.
    #[must_use]
    pub const fn id(&self) -> ::mantis_core::wire::MessageId {
        match self {
            Self::Welcome(_) => <Welcome as ::mantis_core::wire::Message>::ID,
            Self::Refuse(_) => <Refuse as ::mantis_core::wire::Message>::ID,
            Self::SetPosition(_) => <SetPosition as ::mantis_core::wire::Message>::ID,
            Self::ExtensionRefused(_) => <ExtensionRefused as ::mantis_core::wire::Message>::ID,
            Self::ExtensionMessage(_) => <ExtensionMessage as ::mantis_core::wire::Message>::ID,
            Self::FeatureState(_) => <FeatureState as ::mantis_core::wire::Message>::ID,
            Self::PermittedModules(_) => <PermittedModules as ::mantis_core::wire::Message>::ID,
            Self::Transferred(_) => <Transferred as ::mantis_core::wire::Message>::ID,
            Self::ResumeTicket(_) => <ResumeTicket as ::mantis_core::wire::Message>::ID,
            Self::HandOff(_) => <HandOff as ::mantis_core::wire::Message>::ID,
        }
    }

    /// Appends the payload encoding (without the id).
    pub fn encode(&self, out: &mut Vec<u8>) {
        match self {
            Self::Welcome(m) => ::mantis_core::wire::encode_into(m, out),
            Self::Refuse(m) => ::mantis_core::wire::encode_into(m, out),
            Self::SetPosition(m) => ::mantis_core::wire::encode_into(m, out),
            Self::ExtensionRefused(m) => ::mantis_core::wire::encode_into(m, out),
            Self::ExtensionMessage(m) => ::mantis_core::wire::encode_into(m, out),
            Self::FeatureState(m) => ::mantis_core::wire::encode_into(m, out),
            Self::PermittedModules(m) => ::mantis_core::wire::encode_into(m, out),
            Self::Transferred(m) => ::mantis_core::wire::encode_into(m, out),
            Self::ResumeTicket(m) => ::mantis_core::wire::encode_into(m, out),
            Self::HandOff(m) => ::mantis_core::wire::encode_into(m, out),
        }
    }
}

/// Decodes one outbound message without validating it. Unknown ids fail closed.
///
/// # Errors
/// [`::mantis_core::wire::WireError`] for an unknown id or a payload that does
/// not decode exactly.
pub fn decode_outbound(
    id: ::mantis_core::wire::MessageId,
    bytes: &[u8],
) -> Result<Outbound, ::mantis_core::wire::WireError> {
    Ok(match id.0 {
        10 => Outbound::Welcome(::mantis_core::wire::decode_message(bytes)?),
        11 => Outbound::Refuse(::mantis_core::wire::decode_message(bytes)?),
        12 => Outbound::SetPosition(::mantis_core::wire::decode_message(bytes)?),
        13 => Outbound::ExtensionRefused(::mantis_core::wire::decode_message(bytes)?),
        14 => Outbound::ExtensionMessage(::mantis_core::wire::decode_message(bytes)?),
        15 => Outbound::FeatureState(::mantis_core::wire::decode_message(bytes)?),
        16 => Outbound::PermittedModules(::mantis_core::wire::decode_message(bytes)?),
        18 => Outbound::Transferred(::mantis_core::wire::decode_message(bytes)?),
        19 => Outbound::ResumeTicket(::mantis_core::wire::decode_message(bytes)?),
        20 => Outbound::HandOff(::mantis_core::wire::decode_message(bytes)?),
        _ => return Err(::mantis_core::wire::WireError::UnknownMessage(id)),
    })
}
